eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   CAREERS: () => (/* binding */ CAREERS),\n/* harmony export */   CAREER_CATEGORIES: () => (/* binding */ CAREER_CATEGORIES),\n/* harmony export */   INTERESTS: () => (/* binding */ INTERESTS)\n/* harmony export */ });\nconst CAREERS = [\n    {\n        id: \"software-engineering\",\n        title: \"Software Engineer\",\n        category: \"IT\",\n        description: \"Design and build software systems that power the digital world.\",\n        longDescription: \"Software engineers design, develop, and maintain software systems. In South Africa, the tech sector is booming with major firms like Takealot, Standard Bank, and Naspers hiring aggressively. You will work across web, mobile, cloud, and AI technologies. Software engineers typically start at junior level and progress to senior, lead, and architect roles. The field offers excellent remote work opportunities and international career mobility.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 60\n            },\n            {\n                subject: \"English\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 28,\n        maxAPS: 42,\n        salaryRange: {\n            min: 350000,\n            max: 1200000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Problem Solving\",\n            \"Logical Thinking\",\n            \"Teamwork\",\n            \"Continuous Learning\",\n            \"Communication\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\",\n            \"uj\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83D\\uDCBB\",\n        alternativeCareers: [\n            \"data-scientist\",\n            \"cybersecurity-analyst\",\n            \"ux-designer\"\n        ],\n        improvementSubject: \"Mathematics\"\n    },\n    {\n        id: \"medicine\",\n        title: \"Medical Doctor (MBChB)\",\n        category: \"Health\",\n        description: \"Diagnose and treat patients, saving lives across communities.\",\n        longDescription: \"Medicine is one of the most respected and rewarding careers in South Africa. As a doctor, you will complete 6 years of study followed by internship and community service. SA faces a significant doctor shortage especially in rural areas, meaning strong employment prospects. Specialisation options include surgery, paediatrics, psychiatry, and more. The profession demands dedication, empathy, and lifelong learning.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 70\n            },\n            {\n                subject: \"Physical Sciences\",\n                minimumMark: 70\n            },\n            {\n                subject: \"Life Sciences\",\n                minimumMark: 70\n            },\n            {\n                subject: \"English\",\n                minimumMark: 60\n            }\n        ],\n        minAPS: 36,\n        maxAPS: 42,\n        salaryRange: {\n            min: 800000,\n            max: 2500000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Empathy\",\n            \"Critical Thinking\",\n            \"Attention to Detail\",\n            \"Communication\",\n            \"Resilience\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\",\n            \"ukzn\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83E\\uDE7A\",\n        alternativeCareers: [\n            \"pharmacy\",\n            \"nursing\",\n            \"physiotherapy\"\n        ],\n        improvementSubject: \"Life Sciences\"\n    },\n    {\n        id: \"data-scientist\",\n        title: \"Data Scientist\",\n        category: \"IT\",\n        description: \"Extract insights from large datasets to drive business decisions.\",\n        longDescription: \"Data science is one of the fastest growing fields globally and in South Africa. Data scientists use mathematics, statistics, and programming to analyse complex datasets. SA's financial sector (Absa, FNB, Discovery) and tech companies are the biggest employers. You will work with tools like Python, R, SQL, and machine learning frameworks. The field bridges IT, business, and academia, offering diverse career paths.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 65\n            },\n            {\n                subject: \"English\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 30,\n        maxAPS: 42,\n        salaryRange: {\n            min: 450000,\n            max: 1500000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Statistical Analysis\",\n            \"Python/R Programming\",\n            \"Machine Learning\",\n            \"Data Visualisation\",\n            \"Business Acumen\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"Growing\",\n        emoji: \"\\uD83D\\uDCCA\",\n        alternativeCareers: [\n            \"software-engineering\",\n            \"financial-analyst\",\n            \"actuarial-science\"\n        ],\n        improvementSubject: \"Mathematics\"\n    },\n    {\n        id: \"civil-engineering\",\n        title: \"Civil Engineer\",\n        category: \"Engineering\",\n        description: \"Design and build the infrastructure that shapes South Africa.\",\n        longDescription: \"Civil engineers design and oversee construction of roads, bridges, dams, buildings, and water systems. South Africa has massive infrastructure needs, especially in townships and rural areas, creating strong demand. You will work with government (SANRAL, municipalities), construction firms like WBHO and Aveng, or as a consultant. Professional registration with ECSA is required for independent practice. The career combines technical skills with project management and environmental considerations.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 65\n            },\n            {\n                subject: \"Physical Sciences\",\n                minimumMark: 60\n            },\n            {\n                subject: \"English\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 30,\n        maxAPS: 42,\n        salaryRange: {\n            min: 400000,\n            max: 1100000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Technical Drawing\",\n            \"Project Management\",\n            \"Problem Solving\",\n            \"Mathematics\",\n            \"Environmental Awareness\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\",\n            \"uj\",\n            \"ukzn\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83C\\uDFD7️\",\n        alternativeCareers: [\n            \"mechanical-engineering\",\n            \"architecture\",\n            \"quantity-surveying\"\n        ],\n        improvementSubject: \"Physical Sciences\"\n    },\n    {\n        id: \"chartered-accountant\",\n        title: \"Chartered Accountant (CA)\",\n        category: \"Business\",\n        description: \"The gold standard of business qualifications in South Africa.\",\n        longDescription: \"Becoming a CA(SA) is one of the most prestigious and lucrative career paths in South Africa. You will study through SAICA-accredited universities, complete a 3-year training contract (articles) at a firm like Deloitte, PwC, KPMG, or EY, then pass the board exam. CAs work in audit, tax, financial management, and consulting. Many become CFOs and CEOs. The qualification is highly portable internationally.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 60\n            },\n            {\n                subject: \"English\",\n                minimumMark: 55\n            }\n        ],\n        minAPS: 28,\n        maxAPS: 42,\n        salaryRange: {\n            min: 500000,\n            max: 2000000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Analytical Thinking\",\n            \"Attention to Detail\",\n            \"Ethics\",\n            \"Communication\",\n            \"Financial Acumen\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\",\n            \"uj\",\n            \"unisa\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83D\\uDCC8\",\n        alternativeCareers: [\n            \"financial-analyst\",\n            \"data-scientist\",\n            \"law\"\n        ],\n        improvementSubject: \"Mathematics\"\n    },\n    {\n        id: \"law\",\n        title: \"Attorney / Advocate\",\n        category: \"Law\",\n        description: \"Uphold justice and navigate the complex legal landscape of SA.\",\n        longDescription: \"Law in South Africa is a dynamic field shaped by our complex constitutional democracy. You can specialise in criminal law, commercial law, constitutional law, labour law, and more. The LLB degree is 4 years and you must complete articles (for attorneys) or pupillage (for advocates). SA's legal market has large firms like Bowmans and Webber Wentzel, government/public sector, NGOs, and independent practice. The Constitutional Court makes South African law globally respected.\",\n        requiredSubjects: [\n            {\n                subject: \"English\",\n                minimumMark: 60\n            }\n        ],\n        minAPS: 26,\n        maxAPS: 42,\n        salaryRange: {\n            min: 300000,\n            max: 1800000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Critical Thinking\",\n            \"Verbal Communication\",\n            \"Research\",\n            \"Writing\",\n            \"Negotiation\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\",\n            \"uj\",\n            \"ukzn\",\n            \"unisa\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"Medium\",\n        emoji: \"⚖️\",\n        alternativeCareers: [\n            \"chartered-accountant\",\n            \"human-resources\",\n            \"social-work\"\n        ],\n        improvementSubject: \"English\"\n    },\n    {\n        id: \"nursing\",\n        title: \"Professional Nurse\",\n        category: \"Health\",\n        description: \"Be the backbone of South Africa's healthcare system.\",\n        longDescription: \"Nurses are the most essential and numerous healthcare workers in South Africa. The profession has evolved significantly — advanced practice nurses can diagnose and prescribe. You can specialise in ICU, neonatal, psychiatric, oncology nursing and more. Employment opportunities exist in public hospitals, private hospitals (Netcare, Mediclinic), clinics, schools, and occupational health. The SANC (South African Nursing Council) regulates the profession.\",\n        requiredSubjects: [\n            {\n                subject: \"English\",\n                minimumMark: 50\n            },\n            {\n                subject: \"Life Sciences\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 20,\n        maxAPS: 35,\n        salaryRange: {\n            min: 200000,\n            max: 600000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Empathy\",\n            \"Communication\",\n            \"Clinical Skills\",\n            \"Problem Solving\",\n            \"Teamwork\"\n        ],\n        universities: [\n            \"ukzn\",\n            \"uj\",\n            \"unisa\",\n            \"nwu\",\n            \"ufs\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83D\\uDC89\",\n        alternativeCareers: [\n            \"physiotherapy\",\n            \"pharmacy\",\n            \"social-work\"\n        ],\n        improvementSubject: \"Life Sciences\"\n    },\n    {\n        id: \"architecture\",\n        title: \"Architect\",\n        category: \"Arts\",\n        description: \"Shape the built environment and design the spaces we inhabit.\",\n        longDescription: \"Architects design buildings and spaces that balance function, aesthetics, and sustainability. In South Africa, rapid urbanisation means constant demand for housing, commercial, and public buildings. You will need to register with SACAP (SA Council for the Architectural Profession) after completing your degree and internship. Specialisations include residential, commercial, heritage, and landscape architecture. The profession blends creativity with technical precision.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 60\n            },\n            {\n                subject: \"English\",\n                minimumMark: 55\n            }\n        ],\n        minAPS: 28,\n        maxAPS: 42,\n        salaryRange: {\n            min: 350000,\n            max: 900000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Creative Design\",\n            \"Technical Drawing\",\n            \"Spatial Thinking\",\n            \"Project Management\",\n            \"Communication\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"tut\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"Medium\",\n        emoji: \"\\uD83C\\uDFDB️\",\n        alternativeCareers: [\n            \"civil-engineering\",\n            \"quantity-surveying\",\n            \"ux-designer\"\n        ],\n        improvementSubject: \"Mathematics\"\n    },\n    {\n        id: \"pharmacy\",\n        title: \"Pharmacist\",\n        category: \"Health\",\n        description: \"Medicines expert ensuring safe and effective patient care.\",\n        longDescription: \"Pharmacists are critical members of the healthcare team with deep expertise in medications. In SA, you can work in retail pharmacies (Dis-Chem, Clicks), hospital pharmacies, pharmaceutical manufacturing companies (Aspen, Adcock Ingram), or regulatory bodies like SAHPRA. A 4-year BPharm degree is required, followed by registration with the SA Pharmacy Council. The role has expanded to include patient counselling, chronic disease management, and vaccination.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 60\n            },\n            {\n                subject: \"Physical Sciences\",\n                minimumMark: 60\n            },\n            {\n                subject: \"Life Sciences\",\n                minimumMark: 60\n            }\n        ],\n        minAPS: 30,\n        maxAPS: 42,\n        salaryRange: {\n            min: 500000,\n            max: 1100000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Pharmacology Knowledge\",\n            \"Patient Communication\",\n            \"Attention to Detail\",\n            \"Problem Solving\",\n            \"Ethics\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"ukzn\",\n            \"nwu\",\n            \"ufs\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83D\\uDC8A\",\n        alternativeCareers: [\n            \"medicine\",\n            \"nursing\",\n            \"biochemistry\"\n        ],\n        improvementSubject: \"Physical Sciences\"\n    },\n    {\n        id: \"cybersecurity-analyst\",\n        title: \"Cybersecurity Analyst\",\n        category: \"IT\",\n        description: \"Protect organisations from digital threats in an increasingly connected world.\",\n        longDescription: \"Cybersecurity is one of the fastest-growing tech fields globally, and South Africa is no exception. As cyberattacks increase, demand for security professionals has skyrocketed. You will work to protect networks, systems, and data from hackers and breaches. Key employers include banks, government, telecoms (MTN, Vodacom), and consulting firms. Certifications like CISSP, CEH, and CompTIA Security+ enhance career prospects significantly.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 55\n            },\n            {\n                subject: \"English\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 26,\n        maxAPS: 40,\n        salaryRange: {\n            min: 400000,\n            max: 1300000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Network Security\",\n            \"Ethical Hacking\",\n            \"Cryptography\",\n            \"Risk Assessment\",\n            \"Problem Solving\"\n        ],\n        universities: [\n            \"uct\",\n            \"up\",\n            \"uj\",\n            \"tut\",\n            \"nwu\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"Growing\",\n        emoji: \"\\uD83D\\uDD12\",\n        alternativeCareers: [\n            \"software-engineering\",\n            \"data-scientist\",\n            \"network-engineer\"\n        ],\n        improvementSubject: \"Mathematics\"\n    },\n    {\n        id: \"actuarial-science\",\n        title: \"Actuary\",\n        category: \"Business\",\n        description: \"Use mathematics to assess risk for insurance and financial firms.\",\n        longDescription: \"Actuaries are among the highest-paid professionals in South Africa. They use advanced mathematics, statistics, and financial theory to assess and manage risk. Key employers include large insurers (Old Mutual, Sanlam, Discovery, Liberty), reinsurers, and consultancies. You must pass a series of professional exams from the Actuarial Society of South Africa (ASSA). The path is demanding but exceptionally rewarding financially and intellectually.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 80\n            },\n            {\n                subject: \"English\",\n                minimumMark: 55\n            }\n        ],\n        minAPS: 34,\n        maxAPS: 42,\n        salaryRange: {\n            min: 700000,\n            max: 2500000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Advanced Mathematics\",\n            \"Statistical Modelling\",\n            \"Programming\",\n            \"Communication\",\n            \"Business Acumen\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83E\\uDDEE\",\n        alternativeCareers: [\n            \"chartered-accountant\",\n            \"data-scientist\",\n            \"financial-analyst\"\n        ],\n        improvementSubject: \"Mathematics\"\n    },\n    {\n        id: \"social-work\",\n        title: \"Social Worker\",\n        category: \"Education\",\n        description: \"Support vulnerable individuals and communities across South Africa.\",\n        longDescription: \"Social workers are vital to addressing South Africa's social challenges: poverty, abuse, child welfare, substance dependency, and mental health. You will work in government departments (DSD), NGOs like ChildLine and SANCA, hospitals, schools, and corrections facilities. A BSW (Bachelor of Social Work) is required, plus registration with the South African Council for Social Service Professions (SACSSP). While salaries are modest, the impact and job security are significant.\",\n        requiredSubjects: [\n            {\n                subject: \"English\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 18,\n        maxAPS: 32,\n        salaryRange: {\n            min: 180000,\n            max: 450000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Empathy\",\n            \"Communication\",\n            \"Case Management\",\n            \"Report Writing\",\n            \"Community Development\"\n        ],\n        universities: [\n            \"unisa\",\n            \"uj\",\n            \"nwu\",\n            \"ufs\",\n            \"ukzn\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"\\uD83E\\uDD1D\",\n        alternativeCareers: [\n            \"nursing\",\n            \"psychology\",\n            \"education\"\n        ],\n        improvementSubject: \"English\"\n    },\n    {\n        id: \"mechanical-engineering\",\n        title: \"Mechanical Engineer\",\n        category: \"Engineering\",\n        description: \"Design and build the machines that drive South African industry.\",\n        longDescription: \"Mechanical engineers are fundamental to South Africa's mining, manufacturing, automotive, and energy sectors. You will design, analyse, and maintain mechanical systems from mining equipment to power plants. Key employers include Anglo American, Eskom, Toyota SA, and Sasol. Professional registration with ECSA is required. The renewable energy boom (wind, solar) is creating exciting new opportunities for mechanical engineers in South Africa.\",\n        requiredSubjects: [\n            {\n                subject: \"Mathematics\",\n                minimumMark: 65\n            },\n            {\n                subject: \"Physical Sciences\",\n                minimumMark: 65\n            },\n            {\n                subject: \"English\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 30,\n        maxAPS: 42,\n        salaryRange: {\n            min: 420000,\n            max: 1100000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Engineering Design\",\n            \"CAD Software\",\n            \"Mathematics\",\n            \"Problem Solving\",\n            \"Project Management\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"up\",\n            \"stellenbosch\",\n            \"ukzn\",\n            \"tut\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"High\",\n        emoji: \"⚙️\",\n        alternativeCareers: [\n            \"civil-engineering\",\n            \"electrical-engineering\",\n            \"industrial-engineering\"\n        ],\n        improvementSubject: \"Physical Sciences\"\n    },\n    {\n        id: \"ux-designer\",\n        title: \"UX/UI Designer\",\n        category: \"IT\",\n        description: \"Create intuitive and beautiful digital experiences for users.\",\n        longDescription: \"UX/UI design is a rapidly growing field as South African businesses digitise. You will design the look and feel of apps, websites, and software products. Key employers include tech startups, agencies, banks, and retail companies. While not requiring a specific degree (many designers are self-taught or from creative backgrounds), strong portfolio work is essential. Tools include Figma, Adobe XD, and Sketch. The field rewards creativity combined with user empathy and data-driven thinking.\",\n        requiredSubjects: [\n            {\n                subject: \"English\",\n                minimumMark: 50\n            }\n        ],\n        minAPS: 20,\n        maxAPS: 38,\n        salaryRange: {\n            min: 280000,\n            max: 900000,\n            currency: \"ZAR\"\n        },\n        skills: [\n            \"Visual Design\",\n            \"User Research\",\n            \"Prototyping\",\n            \"Figma/Sketch\",\n            \"Communication\"\n        ],\n        universities: [\n            \"uct\",\n            \"wits\",\n            \"tut\",\n            \"cput\"\n        ],\n        nsfasFunded: true,\n        demandLevel: \"Growing\",\n        emoji: \"\\uD83C\\uDFA8\",\n        alternativeCareers: [\n            \"software-engineering\",\n            \"graphic-design\",\n            \"architecture\"\n        ],\n        improvementSubject: \"English\"\n    }\n];\nconst CAREER_CATEGORIES = [\n    \"IT\",\n    \"Health\",\n    \"Business\",\n    \"Engineering\",\n    \"Law\",\n    \"Education\",\n    \"Arts\",\n    \"Science\"\n];\nconst INTERESTS = [\n    {\n        id: \"technology\",\n        label: \"Technology & Coding\",\n        emoji: \"\\uD83D\\uDCBB\"\n    },\n    {\n        id: \"health\",\n        label: \"Health & Medicine\",\n        emoji: \"\\uD83C\\uDFE5\"\n    },\n    {\n        id: \"business\",\n        label: \"Business & Finance\",\n        emoji: \"\\uD83D\\uDCC8\"\n    },\n    {\n        id: \"engineering\",\n        label: \"Engineering & Building\",\n        emoji: \"\\uD83D\\uDD27\"\n    },\n    {\n        id: \"arts\",\n        label: \"Arts & Design\",\n        emoji: \"\\uD83C\\uDFA8\"\n    },\n    {\n        id: \"law\",\n        label: \"Law & Justice\",\n        emoji: \"⚖️\"\n    },\n    {\n        id: \"science\",\n        label: \"Science & Research\",\n        emoji: \"\\uD83D\\uDD2C\"\n    },\n    {\n        id: \"people\",\n        label: \"Working with People\",\n        emoji: \"\\uD83E\\uDD1D\"\n    },\n    {\n        id: \"education\",\n        label: \"Teaching & Education\",\n        emoji: \"\\uD83D\\uDCDA\"\n    },\n    {\n        id: \"environment\",\n        label: \"Environment & Nature\",\n        emoji: \"\\uD83C\\uDF3F\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/careers.ts\n");

